  function fmt(n, d) {
    d = d === undefined ? 1 : d;
    var v = round(n, d);
    if (Math.abs(v - Math.round(v)) < 1e-9) return String(Math.round(v));
    return v.toFixed(d).replace('-', '−');
  }
  function tickFmt(v, step) {
    var d = step >= 1 ? 0 : step >= 0.1 ? 1 : step >= 0.01 ? 2 : 3;
    return fmt(v, d);
