    svg.appendChild(grid);
    svg.appendChild(axes);
    if (sym) svg.appendChild(sym);
    svg.appendChild(curve);
    svg.appendChild(marks);
    svg.appendChild(labels);

    if (!entered && !reduced) {
      try {
        var len = curve.getTotalLength();
        if (len > 0) {
          curve.style.strokeDasharray = String(len);
          curve.style.strokeDashoffset = String(len);
          curve.getBoundingClientRect();
          curve.style.transition = 'stroke-dashoffset 620ms ease-out';
          curve.style.strokeDashoffset = '0';
          curve.addEventListener('transitionend', function () {
            curve.style.strokeDasharray = '';
            curve.style.strokeDashoffset = '';
            curve.style.transition = '';
          }, { once: true });
        }
      } catch (err) { /* 曲线动画不可用时保持静态绘制 */ }
    }

    if (refit && !reduced && typeof svg.animate === 'function') {
      var now = Date.now();
      if (now - lastFitAt > 220) {
        lastFitAt = now;
        try {
          svg.animate(
            [{ opacity: 0.55 }, { opacity: 1 }],
            { duration: 200, easing: 'ease-out' }
          );
        } catch (err) { /* 忽略动画失败 */ }
      }
    }
  }

  function render(raw) {
    var a = round(Number(raw.a) || 0, 1);
    var b = round(Number(raw.b) || 0, 1);
    var c = round(Number(raw.c) || 0, 1);

    var eq = equation(a, b, c);
    var shapeText;
    var noteText;
    var vertexText;
    var symText;
    var rootText;

    if (Math.abs(a) < 1e-6) {
      shapeText = Math.abs(b) < 1e-6 ? '常函数' : '一次函数';
      vertexText = '—';
      symText = '—';
      if (Math.abs(b) < 1e-6) {
        rootText = Math.abs(c) < 1e-9 ? '与 x 轴重合' : '无交点';
        noteText = 'a = b = 0，图像是一条水平直线 y = c。';
      } else {
        rootText = 'x = ' + fmt(-c / b);
        noteText = 'a = 0，图像退化为直线 y = bx + c。';
      }
    } else {
      var h = -b / (2 * a);
      var k = c - b * b / (4 * a);
      var disc = b * b - 4 * a * c;
      shapeText = a > 0 ? '开口向上' : '开口向下';
      noteText = '拖动滑块，抛物线、顶点与 x 轴交点会实时更新。';
      vertexText = '(' + fmt(h) + ', ' + fmt(k) + ')';
      symText = 'x = ' + fmt(h);
      if (disc > 1e-9) {
        var sq = Math.sqrt(disc);
        var r1 = (-b - sq) / (2 * a);
        var r2 = (-b + sq) / (2 * a);
        if (r1 > r2) {
          var tr = r1;
          r1 = r2;
          r2 = tr;
        }
        rootText = 'x₁ = ' + fmt(r1) + ' · x₂ = ' + fmt(r2);
      } else if (disc > -1e-9) {
        rootText = 'x₁ = x₂ = ' + fmt(h);
      } else {
        rootText = '无实数根';
      }
    }

    q('equation').textContent = eq;
    q('shape').textContent = shapeText;
    q('note').textContent = noteText;
    q('vertex').textContent = vertexText;
    q('symmetry').textContent = symText;
    q('roots').textContent = rootText;
    q('a').textContent = fixed1(a);
    q('b').textContent = fixed1(b);
    q('c').textContent = fixed1(c);

    plotEl.setAttribute('aria-label', '函数 ' + eq + ' 的图像');

    lastParams = { a: a, b: b, c: c };
    draw(lastParams);
    entered = true;

    return {
      equation: eq,
      shape: shapeText,
      note: noteText,
      vertex: vertexText,
      symmetry: symText,
      roots: rootText,
      a: fixed1(a),
      b: fixed1(b),
      c: fixed1(c)
    };
  }

  if (window.dshViz && typeof window.dshViz.bind === 'function') {
    window.dshViz.bind('#quad-demo', render);
  } else {
    render({ a: 1, b: -2, c: -3 });
  }

  if (typeof ResizeObserver === 'function') {
    var ro = new ResizeObserver(function () {
      if (!lastParams) return;
      var w = Math.round(plotEl.clientWidth || 0);
      var h = Math.round(plotEl.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw(lastParams);
    });
    ro.observe(plotEl);
  }
})();
</script>", "title": "二次函数交互演示", "mode": "inline"}

