Let me write the equation function:

```
function num(n) {
  var v = round(n, 1);
  if (Math.abs(v) < 1e-9) return '0';
  return String(v).replace('-', '−');
}
function coef(n) { // abs coefficient display, omit 1
  var v = round(Math.abs(n), 1);
  return Math.abs(v - 1) < 1e-9 ? '' : num(v);
}
function equation(a,b,c) {
  var s = 'y = ';
  var hasTerm = false;
  if (Math.abs(a) >= 1e-6) {
    s += (a < 0 ? '−' : '') + coef(a) + 'x²';
    hasTerm = true;
  }
  if (Math.abs(b) >= 1e-6) {
    if (hasTerm) s += b < 0 ? ' − ' : ' + ';
    else if (b < 0) s += '−';
    s += coef(b) + 'x';
    hasTerm = true;
  }
  if (Math.abs(c) >= 1e-6 || !hasTerm) {
    if (hasTerm) s += c < 0 ? ' − ' : ' + ';
    else if (c < 0) s += '−';
    s += num(Math.abs(c));
  }
  return s;
}
```

