(function () {
  'use strict';
  var root = document.getElementById('quad-demo');
  if (!root) return;
  var NS = 'http://www.w3.org/2000/svg';
  var plotEl = root.querySelector('.quad-plot');
  var svg = root.querySelector('.quad-plot svg');
  var entered = false;
  var lastWin = null;
  var lastParams = null;
  var lastW = 0;
  var lastH = 0;
  var lastFitAt = 0;
  var reduced = false;

  try {
    reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  } catch (e) {
    reduced = false;
  }

  function q(key) {
    return root.querySelector('[data-viz-out="' + key + '"]');
  }

  function el(name, attrs, text) {
    var node = document.createElementNS(NS, name);
    if (attrs) {
      for (var key in attrs) {
        if (Object.prototype.hasOwnProperty.call(attrs, key) && attrs[key] !== null && attrs[key] !== undefined) {
          node.setAttribute(key, attrs[key]);
        }
      }
    }
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function round(n, d) {
    var m = Math.pow(10, d === undefined ? 1 : d);
