          x1: X(hSym), y1: padT,
          x2: X(hSym), y2: padT + ih,
          class: 'sym-line'
        });
      }
    }

    var n = Math.min(640, Math.max(160, Math.round(iw * 2)));
    var d = '';
    for (var i = 0; i <= n; i += 1) {
      var xx = win.xmin + spanX * (i / n);
      var yy = a * xx * xx + b * xx + c;
      d += (i === 0 ? 'M' : 'L') + X(xx).toFixed(2) + ',' + Y(yy).toFixed(2);
    }
    var curve = el('path', {
      d: d,
      class: 'curve',
      'clip-path': 'url(#quad-demo-clip)'
    });

    var both = xVisible && yVisible;
    var xLabelY = xVisible ? axisY + 15 : padT + ih + 16;

    labels.appendChild(el('text', {
      x: axisX - 6,
      y: axisY + 14,
      'text-anchor': 'end',
      class: 'tick-text'
    }, '0'));

    var lastRight = -Infinity;
    xTicks.forEach(function (t) {
      if (both && Math.abs(t) < 1e-9) return;
      var label = tickFmt(t, xStep);
      var px = X(t);
      var half = label.length * 3.3 + 2;
      if (px - half < 2 || px + half > plotW - 2) return;
      if (px - half < lastRight + 6) return;
      lastRight = px + half;
      labels.appendChild(el('text', {
        x: px,
        y: xLabelY,
        'text-anchor': 'middle',
        class: 'tick-text'
      }, label));
    });

    yTicks.forEach(function (t) {
      if (both && Math.abs(t) < 1e-9) return;
      labels.appendChild(el('text', {
        x: padL - 8,
        y: Y(t) + 3.5,
        'text-anchor': 'end',
        class: 'tick-text'
      }, tickFmt(t, yStep)));
    });

    if (both) {
      labels.appendChild(el('text', {
        x: axisX - 6,
        y: axisY + 14,
        'text-anchor': 'end',
        class: 'tick-text'
      }, '0'));
    }

    if (xVisible) {
      labels.appendChild(el('text', {
        x: padL + iw,
        y: axisY - 10,
        class: 'axis-label axis-label-x',
        'text-anchor': 'end'
      }, 'x'));
    }
    if (yVisible) {
      var yLabX = Math.min(axisX + 10, padL + iw - 14);
      labels.appendChild(el('text', {
        x: yLabX,
        y: padT + 14,
        class: 'axis-label axis-label-y',
        'text-anchor': 'start'
      }, 'y'));
    }

    if (Math.abs(a) >= 1e-6) {
      var disc = b * b - 4 * a * c;
      if (disc >= -1e-9) {
        var sq = Math.sqrt(Math.max(0, disc));
        var r1 = (-b - sq) / (2 * a);
        var r2 = (-b + sq) / (2 * a);
        if (r1 > r2) {
          var tr = r1;
          r1 = r2;
          r2 = tr;
        }
        var p1 = X(r1);
        var p2 = X(r2);
        var rootY = axisY;

        if (r1 >= win.xmin - 1e-9 && r1 <= win.xmax + 1e-9) {
          marks.appendChild(el('circle', { cx: p1, cy: rootY, r: 3.5, class: 'root-dot' }));
        }
        if (Math.abs(r2 - r1) > 1e-9 && r2 >= win.xmin - 1e-9 && r2 <= win.xmax + 1e-9) {
          marks.appendChild(el('circle', { cx: p2, cy: rootY, r: 3.5, class: 'root-dot' }));
        }

        var rootLabelY = Math.min(rootY + 29, plotH - 4);

        function addRootLabel(px, text) {
          var tw = text.length * 6.2;
          var anchor = 'middle';
          var lx = px;
          if (px - tw / 2 < 2) {
            anchor = 'start';
            lx = Math.max(2, px);
          } else if (px + tw / 2 > plotW - 2) {
            anchor = 'end';
            lx = Math.min(plotW - 2, px);
          }
          labels.appendChild(el('text', {
            x: lx,
            y: rootLabelY,
            'text-anchor': anchor,
            class: 'root-label'
          }, text));
        }

        if (Math.abs(p2 - p1) >= 104) {
          addRootLabel(p1, 'x₁ = ' + fmt(r1));
          addRootLabel(p2, 'x₂ = ' + fmt(r2));
        } else if (Math.abs(disc) < 1e-9) {
          addRootLabel((p1 + p2) / 2, 'x₁,₂ = ' + fmt(r1));
        } else {
          addRootLabel((p1 + p2) / 2, 'x₁ = ' + fmt(r1) + ' · x₂ = ' + fmt(r2));
        }
      }
    }

    if (Math.abs(a) >= 1e-6) {
      var hV = -b / (2 * a);
      var kV = c - b * b / (4 * a);
      var vx = X(hV);
      var vy = Y(kV);
      marks.appendChild(el('circle', { cx: vx, cy: vy, r: 4.5, class: 'vertex-dot' }));

      var vText = '顶点 (' + fmt(hV) + ', ' + fmt(kV) + ')';
      var vWidth = vText.length * 7.2;
      var vLx = vx + 9;
      var vAnchor = 'start';
      if (vLx + vWidth > plotW - 4) {
        vLx = vx - 9;
        vAnchor = 'end';
      }
      var vLy = vy - 10;
      if (vLy < padT + 12) vLy = vy + 18;
      labels.appendChild(el('text', {
        x: vLx,
        y: vLy,
        'text-anchor': vAnchor,
        class: 'vertex-label'
      }, vText));
    }

    svg.appendChild(defs);
    svg.appendChild(grid);
    svg.appendChild(axes);
    if (sym) svg.appendChild(sym);
    svg.appendChild(curve);
    svg.appendChild(marks);
    svg.appendChild(labels);

    if (!entered && !reduced) {
      try {
        var len = curve.getTotalLength();
        if (len > 0) {
          curve.style.strokeDasharray = String(len);
          curve.style.strokeDashoffset = String(len);
          curve.getBoundingClientRect();
          curve.style.transition = 'stroke-dashoffset 620ms ease-out';
          curve.style.strokeDashoffset = '0';
          curve.addEventListener('transitionend', function () {
            curve.style.strokeDasharray = '';
            curve.style.strokeDashoffset = '';
            curve.style.transition = '';
          }, { once: true });
        }
      } catch (err) { /* 曲线动画不可用时保持静态绘制 */ }
    }

    if (refit && !reduced && typeof svg.animate === 'function') {
      var now = Date.now();
      if (now - lastFitAt > 220) {
        lastFitAt = now;
        try {
          svg.animate(
            [{ opacity: 0.55 }, { opacity: 1 }],
            { duration: 200, easing: 'ease-out' }
          );
        } catch (err) { /* 忽略动画失败 */ }
      }
    }
  }

  function render(raw) {
    var a = round(Number(raw.a) || 0, 1);
    var b = round(Number(raw.b) || 0, 1);
    var c = round(Number(raw.c) || 0, 1);

    var eq = equation(a, b, c);
    var shapeText;
    var noteText;
    var vertexText;
    var symText;
    var rootText;

    if (Math.abs(a) < 1e-6) {
      shapeText = Math.abs(b) < 1e-6 ? '常函数' : '一次函数';
      vertexText = '—';
      symText = '—';
      if (Math.abs(b) < 1e-6) {
        rootText = Math.abs(c) < 1e-9 ? '与 x 轴重合' : '无交点';
        noteText = 'a = b = 0，图像是一条水平直线 y = c。';
      } else {
        rootText = 'x = ' + fmt(-c / b);
        noteText = 'a = 0，图像退化为直线 y = bx + c。';
      }
    } else {
      var h = -b / (2 * a);
      var k = c - b * b / (4 * a);
      var disc = b * b - 4 * a * c;
      shapeText = a > 0 ? '开口向上' : '开口向下';
      noteText = '拖动滑块，抛物线、顶点与 x 轴交点会实时更新。';
      vertexText = '(' + fmt(h) + ', ' + fmt(k) + ')';
      symText = 'x = ' + fmt(h);
      if (disc > 1e-9) {
        var sq = Math.sqrt(disc);
        var r1 = (-b - sq) / (2 * a);
        var r2 = (-b + sq) / (2 * a);
        if (r1 > r2) {
          var tr = r1;
          r1 = r2;
          r2 = tr;
        }
        rootText = 'x₁ = ' + fmt(r1) + ' · x₂ = ' + fmt(r2);
      } else if (disc > -1e-9) {
        rootText = 'x₁ = x₂ = ' + fmt(h);
      } else {
        rootText = '无实数根';
      }
    }

    q('equation').textContent = eq;
    q('shape').textContent = shapeText;
    q('note').textContent = noteText;
    q('vertex').textContent = vertexText;
    q('symmetry').textContent = symText;
    q('roots').textContent = rootText;
    q('a').textContent = fixed1(a);
    q('b').textContent = fixed1(b);
    q('c').textContent = fixed1(c);

    plotEl.setAttribute('aria-label', '函数 ' + eq + ' 的图像');

    lastParams = { a: a, b: b, c: c };
    draw(lastParams);
    entered = true;

    return {
      equation: eq,
      shape: shapeText,
      note: noteText,
      vertex: vertexText,
      symmetry: symText,
      roots: rootText,
      a: fixed1(a),
      b: fixed1(b),
      c: fixed1(c)
    };
  }

  if (window.dshViz && typeof window.dshViz.bind === 'function') {
    window.dshViz.bind('#quad-demo', render);
  } else {
    render({ a: 1, b: -2, c: -3 });
  }

  if (typeof ResizeObserver === 'function') {
    var ro = new ResizeObserver(function () {
      if (!lastParams) return;
      var w = Math.round(plotEl.clientWidth || 0);
      var h = Math.round(plotEl.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw(lastParams);
    });
    ro.observe(plotEl);
  }
})();
</script>", "title": "二次函数交互演示", "mode": "inline"}

